// Routage : '/claude ...' -> bridge Claude opus (forfait) ; sinon -> local-gemma.
// Remplace les 2 placeholders par les vraies clés (LITELLM_MASTER_KEY et BRIDGE_TOKEN du .env).
const LITELLM_KEY = 'CHANGEME_LITELLM_MASTER_KEY';
const BRIDGE_TOKEN = 'CHANGEME_BRIDGE_TOKEN';

const text = ($json.body?.text || '').trim();
const isClaude = /^\/claude\b/i.test(text);
let reply;

if (isClaude) {
  const prompt = text.replace(/^\/claude\s*/i, '');
  const res = await this.helpers.httpRequest({
    method: 'POST',
    url: 'http://host.docker.internal:8088/run',
    headers: { Authorization: 'Bearer ' + BRIDGE_TOKEN, 'Content-Type': 'application/json' },
    body: { prompt },
    json: true,
    timeout: 120000,
  });
  reply = res.result;
} else {
  const res = await this.helpers.httpRequest({
    method: 'POST',
    url: 'http://litellm:4000/v1/chat/completions',
    headers: { Authorization: 'Bearer ' + LITELLM_KEY, 'Content-Type': 'application/json' },
    body: { model: 'local-gemma', messages: [{ role: 'user', content: text }], max_tokens: 2048 },
    json: true,
    timeout: 120000,
  });
  reply = res.choices[0].message.content;
}

return [{ json: { reply } }];
